-- TAX03B: initial MXMED curated study catalog, exclusively from existing selector options.
-- Canonical source decisions and exclusions: modules/clinical/catalog/tax03b_source_curation.json.
-- Historical document payloads and external code mappings are untouched.
SET @tax03b_has_provenance := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='clinical_study_types' AND COLUMN_NAME='seed_provenance');
SET @tax03b_sql := IF(@tax03b_has_provenance=0, 'ALTER TABLE clinical_study_types ADD COLUMN seed_provenance VARCHAR(120) NULL', 'DO 0');
PREPARE tax03b_stmt FROM @tax03b_sql;
EXECUTE tax03b_stmt;
DEALLOCATE PREPARE tax03b_stmt;
SET @tax03b_has_genetica := (SELECT COUNT(*) FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME='ck_study_type_category' AND CHECK_CLAUSE LIKE '%GENETICA%');
SET @tax03b_sql := IF(@tax03b_has_genetica=0, 'ALTER TABLE clinical_study_types DROP CHECK ck_study_type_category, ADD CONSTRAINT ck_study_type_category CHECK (category_key IN (''LABORATORIO'',''IMAGEN'',''CARDIOVASCULAR'',''OFTALMOLOGIA'',''NEUROFISIOLOGIA'',''FUNCION_PULMONAR'',''AUDIOLOGIA'',''DENTAL'',''PATOLOGIA'',''ENDOSCOPIA'',''SUENO'',''GENETICA'',''OTROS''))', 'DO 0');
PREPARE tax03b_stmt FROM @tax03b_sql;
EXECUTE tax03b_stmt;
DEALLOCATE PREPARE tax03b_stmt;

-- Idempotent insert; any existing identity is retained without modifying it.
ON DUPLICATE KEY UPDATE study_type_key=study_type_key;
